<?php
declare(strict_types=1);
namespace Liberu\RealEstate\PortalsReportingApi\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Http\JsonResponse; use Liberu\RealEstate\PortalsReporting\Models\SavedReport;
final class SavedReportController { public function store(Request $r):JsonResponse{$u=$r->user();abort_unless($u?->current_team_id!==null,403);$d=$r->validate(['name'=>'required|string|max:255','type'=>'required|string|max:100','filters'=>'nullable|array','is_shared'=>'boolean']);return response()->json(['data'=>SavedReport::create([...$d,'team_id'=>$u->current_team_id,'created_by'=>$u->getAuthIdentifier()])],201);} public function show(Request $r,SavedReport $savedReport):JsonResponse{$u=$r->user();abort_unless((string)$u?->current_team_id===(string)$savedReport->team_id&&$savedReport->visibleTo($u->getAuthIdentifier()),404);return response()->json(['data'=>$savedReport]);} public function run(Request $r,SavedReport $savedReport):JsonResponse{$this->authorize($r,$savedReport);return response()->json(['data'=>['report'=>$savedReport->type,'filters'=>$savedReport->filters??[]]]);} public function export(Request $r,SavedReport $savedReport):\Symfony\Component\HttpFoundation\StreamedResponse{$this->authorize($r,$savedReport);return response()->streamDownload(fn()=>print "report\n".$savedReport->type."\n",'report.csv',['Content-Type'=>'text/csv']);} private function authorize(Request $r,SavedReport $s):void{$u=$r->user();abort_unless((string)$u?->current_team_id===(string)$s->team_id&&$s->visibleTo($u->getAuthIdentifier()),404);} }
